{
  "findings": [
    {
      "check_id": "CKV2_AWS_22",
      "title": "Ensure an IAM User does not have access to the console",
      "resource": "aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user",
      "severity": "MEDIUM",
      "explanation": "The IAM user 'privesc15-PassExistingRoleToNewLambdaThenInvoke-user' is created without explicitly disabling console access, potentially allowing unintended access."
    }
  ],
  "patched_code": "resource \"aws_iam_user\" \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\" {\n  name          = \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\"\n  path          = \"/\"\n  force_destroy = true\n}\n\nresource \"aws_iam_user_login_profile\" \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\" {\n  count = 0\n  user = aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user.name\n}\n",
  "fix_summary": "Added a count = 0 to aws_iam_user_login_profile to prevent console access by default for the IAM user."
}
